"""Task tools and dated original-client references; no remote gameplay data requests."""
from pathlib import Path
from html import escape
import json,re
from azeroth_survivors_content import P,SOURCES,a,ext,ref,para,steps,table
ROOT=Path(__file__).resolve().parents[1]
TOOL_PATHS={P,P+'best-class/',P+'troubleshooting/',P+'abilities/'}
LANGS={'en':'English','pl':'Polski','cs':'Čeština','de':'Deutsch','pt':'Português','es':'Español','fr':'Français','ro':'Română','tr':'Türkçe','ru':'Русский','uk':'Українська','zh':'简体中文','ja':'日本語','ko':'한국어'}

def tool_assets(path,html):
 if path in TOOL_PATHS:
  html=html.replace('</head>','<link rel="stylesheet" href="/assets/azeroth-survivors/tools.css"><script defer src="/assets/azeroth-survivors/tools.js"></script></head>')
 return html

def p(t):return para(t+ref('tools130'))

def quiz():
 groups=[('style','Where do you want to fight?',[('melee','Close to the pack'),('range','At range'),('summon','Alongside pets or demons')]),('goal','What needs help?',[('survival','Room to survive'),('damage','A working damage route')]),('progress','What character are you choosing for?',[('fresh','Fresh character'),('developed','Developed talents')])]
 h='<form id="class-finder" class="az-tool"><p>Choose a playstyle, goal and progression state. This gives an editorial starting suggestion, not a measured strongest class.</p>'
 for name,label,options in groups:
  h+='<fieldset><legend>'+label+'</legend>'+''.join(f'<label><input type="radio" name="{name}" value="{v}"> {t}</label>'for v,t in options)+'</fieldset>'
 h+='<button type="reset">Clear choices</button></form><div id="class-tray" class="az-tray" hidden><span id="class-status" role="status">0 / 3 chosen</span><button id="class-open" type="button" disabled>View recommendation</button></div>'
 h+='<dialog id="class-result" aria-labelledby="class-result-title"><h2 id="class-result-title">Your starting direction</h2><div id="class-result-body"></div><button id="class-close" type="button">Close recommendation</button></dialog><noscript><p>Use the playstyle table below to choose a class without JavaScript.</p></noscript>'
 return h

def names_table():
 d=json.loads((ROOT/'data/azeroth-spell-names.json').read_text(encoding='utf8'))
 h='<form class="az-tool" id="spell-filter"><label>Find a spell in any listed language <input type="search" id="spell-query" maxlength="120" autocomplete="off"></label><label>Class <select id="spell-class"><option value="">All classes</option>'+''.join(f'<option value="{c}">{c.title()}</option>'for c in dict.fromkeys(s['class']for s in d['spells']))+'</select></label><label>Client language <select id="spell-language">'+''.join(f'<option value="{v}">{t}</option>'for v,t in LANGS.items())+'</select></label><button type="reset">Reset filters</button><p id="spell-status" role="status">103 names in this dated snapshot</p></form>'
 rows=[]
 for s in d['spells']:
  names=escape(json.dumps(s['names'],ensure_ascii=False),quote=True);c=s['class'];english=escape(s['names']['en'])
  rows.append(f'<tr data-spell-class="{c}" data-names="{names}"><td>'+a('builds/'+c+'/',english)+f'</td><td data-client-name>{english}</td><td>'+a('builds/'+c+'/',c.title()+' route')+'</td></tr>')
 h+='<div class="table-wrap" tabindex="0" role="region" aria-label="Spell name lookup"><table><thead><tr><th scope="col">English name</th><th scope="col">Selected client name</th><th scope="col">Class &amp; guide</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
 return h

def new_pages():
 base=dict(review_note='Edited 1 November 2026 · Original v0.130.0 snapshot from 30 October; launcher text from 29 October · Source research, not a current-version or full-run test')
 trouble=dict(base,id='AZT01',slug='troubleshooting/',title='Azeroth Survivors Not Loading: WebGPU & Error Help',h1='Find the cause before reloading your game',desc='Troubleshoot Azeroth Survivors WebGPU errors, black screens, busy loading and addon problems. Check local browser capability before changing your save.',answer='Match the visible symptom first: no WebGPU, no usable graphics adapter, loading that still advances, or a server refusal. Keep an export before changing browser, host or stored data. The local check below tests capability; it does not test the game server or guarantee a playable run.'+ref('launcher'),parts=[
 ('triage','Choose the symptom you actually see',table(['What you see','First check','Next step'],[
 ['No WebGPU warning','The browser does not expose the needed GPU entry point.', '<a href="#gpu-check">Run the local capability check</a>; inspect browser acceleration and current support.'],
 ['No usable graphics card / adapter','The API can exist without an available adapter.','Check graphics acceleration, graphics drivers and which GPU the browser uses.'],
 ['Black screen with advancing download / preparation','Initial resources can still be loading.','Watch whether progress changes; avoid repeatedly discarding a progressing load.'],
 ['Too many people are playing','A server or resource refusal is different from a GPU error.','Keep progress intact; retry later or inspect the original Windows download.'],
 ['Fake website detected','The original launcher checks its host and frame.','Open the original directly, or read the separate-provider scope of our Play page.'],
 ['Missing progress','Host, browser and profile may differ.','Return to the previous host/profile before clearing anything. '+a('save-backup/','Save recovery checks')],
 ['Addon missing or HUD broken','Installation, version or overlapping HUD packages.','Disable the suspect addon and compare. '+a('addons/','Install and troubleshoot addons')]])+para('These branches interpret the dated original launcher and client text; a matching symptom does not establish one universal cause. '+ref('launcher')+ref('tools130'))),
 ('gpu-check','Check WebGPU in this browser', '<div class="az-tool"><p>Runs only when clicked. No GPU name is collected, nothing is uploaded and no game files are fetched.</p><button id="gpu-run" type="button">Check browser capability</button><p id="gpu-result" role="status" aria-live="polite">Not checked yet.</p><noscript><p>JavaScript is required for this check. Use the symptom table and your browser’s graphics diagnostics instead.</p></noscript></div>'+para('The check asks whether this secure page exposes WebGPU and whether requestAdapter returns an adapter. An available adapter does not verify game features, graphics stability, performance or touch controls. '+ref('webgpu'))),
 ('black-screen','If loading stops or the screen stays black',steps(['Record the exact message and whether a progress counter changes.','Open the original directly in its own tab; do not import your only save into an unfamiliar host.','If graphics capability is missing, inspect the browser’s acceleration setting and graphics diagnostics, then restart after a relevant change.','If capability is available but the game still fails, keep the host, game version, device, browser and failure stage with your report.','Use the creator’s linked download or community route when the browser route is unsuitable. Do not erase storage as a generic loading fix.'])+para(a('download-platforms/','Original download routes')+' · '+a('mobile/','Phone and Steam Deck evidence')+ref('launcher'))),
 ('performance','A low frame rate is a different problem',p('If the game reaches the world, first compare its graphics/display settings and reduce background GPU load. Change one setting at a time. An addon error, an overloaded GPU and a server refusal require different checks; no FPS improvement or universal preset is measured here. Preserve the existing save before testing a different client.')),
 ('help','What to include when asking for help',para('Include the exact host, displayed game version, browser/OS, device, visible error and whether failure happens during download, preparation, menus or a run. Share relevant screenshots without account or save contents. '+ext('https://discord.gg/azerothsurvivors','Discord · creator community linked by the original launcher')+ref('launcher')))],related=[('beginners-guide/','Original controls and startup'),('save-backup/','Protect progress'),('download-platforms/','Choose a platform route')])
 abilities=dict(base,id='AZT02',slug='abilities/',title='Azeroth Survivors Spell Names: Class & Language Lookup',h1='Find a spell name, then open its class route',desc='Search 103 Azeroth Survivors spell names by class or client language from the original v0.130 snapshot. Connect the name you see to an English build guide.',answer='Search a spell name in English or another listed client language, narrow it by class and open the relevant route. This lookup covers 103 class-pool names from the original v0.130.0 snapshot, not a current damage ranking or a complete table of upgrade effects.'+ref('tools130'),parts=[
 ('lookup','Search the original spell-name snapshot',names_table()+p('Names come from the original client’s localized strings. Some translations remain in English. Racial abilities and talent-only names are excluded. The class grouping follows the captured picker/Codex pools; this is not proof that every name is a selectable opening spell.')),
 ('starter','A name in the pool is not necessarily your starter',table(['Character state','How to use the result'],[['Fresh character','Check the picker’s actual starting spell, then support the attack you have.'],['Talent changes the opener','Read the allocated milestone or capstone; do not assume every character starts identically.'],['Spell is missing from an offer','A pool entry is not a guaranteed next card. Use the working attack or a useful survival choice.'],['Another version shows a different name or effect','Read its current card and version; do not transfer rank values from this name index.']])+p(a('builds/','Compare class routes')+' · '+a('talents/','Check gates and point budgets'))),
 ('use','Use names to make a practical choice',p('For example, search 火球术 and select Mage to find Fireball, then use the Mage route to separate a fresh opening from a developed Fire, Frost or Arcane plan. Searching a translated name does not change your game language or your save. '+a('builds/mage/','Mage choices'))),
 ('scope','Version and data limits',p('The name set is a preserved 30 October snapshot, re-read on 1 November. It intentionally supplies no damage score, rarity multiplier or inferred rank value. Check the card shown in your running client before replacing a spell or a build-defining amulet. '+a('items/','Compare the item you are offered')))],related=[('builds/','Choose a build route'),('best-class/','Choose a class'),('items/','Jewelry decisions')])
 return [trouble,abilities]

def apply_tools(pages):
 SOURCES['tools130']=('https://wow.aethus.pl/','Aethus · original snapshot','English and localized original v0.130.0 / e7d9dd47 snapshot captured 30 October 2026; re-read 1 November. Single primary source. Latest live launcher retrieval returned HTTP403 on 1 November; no current-version, full-run or all-rank test claimed.')
 SOURCES['webgpu']=('https://developer.mozilla.org/en-US/docs/Web/API/GPU/requestAdapter','MDN · GPU.requestAdapter','Read 1 November 2026. Secure-context API may return no adapter; this guide’s local capability check is not a game benchmark.')
 SOURCES['azerloot']=('https://github.com/Kindagrey/Azerloot','Kindagrey · Azerloot','Author README read 1 November 2026. Loot book, wishlist and run-history claims are author documentation, not our compatibility test. No package or copyrighted data copied.')
 SOURCES['sdui']=('https://github.com/migwynkriid13/SurvivorsDragonUi','migwynkriid13 · SurvivorsDragonUi','Author README read 1 November 2026. HUD editing and commands are author documentation; not installed or run by this site.')
 thirds={
 'warrior':('Arms: bleed-supported direct hits','Trauma links damage to enemies carrying your DoTs; Deep Wounds supplies a critical-hit bleed. Sweeping Strikes supports nearby hits, and Mortal Wounds changes the opener to Mortal Strike. Its kill-based refresh needs a killing blow.', ['Before the endpoint, keep Cleave functional and use Rend when it serves the bleed plan.','Support the allocated direct-hit and bleed interactions; do not count kill refreshes as constant isolated-boss casts.','If contact ends the run, take recovery or defence before adding another conditional damage effect.']),
 'paladin':('Holy: Holy Shock and periodic holy bursts','Divine Favor changes the opener to Holy Shock and adds jumps. Daybreak links Holy Shock criticals to a free Holy Wrath, while Light’s Grace adds periodic Holy Wrath.', ['Check whether Divine Favor is allocated before planning a Holy Shock start.','Support the Holy Shock and critical interaction you actually have; this differs from shield-break damage.','Take suitable defence if you cannot stay alive to deliver those casts.']),
 'hunter':('Survival: traps before pet assumptions','Entrapment gives trap hits a root chance. Wyvern Sting changes the opener to Frost Trap and sets an automatic Explosive Trap. These benefits are conditional on allocated talents.', ['On a fresh Hunter, maintain Auto Shot while developing useful traps.','After Wyvern Sting, draft for the changed opening and trap coverage.','Compare actual boss damage when adds are absent; control is not a guaranteed boss kill.']),
 'priest':('Holy: Smite criticals and Holy Nova','Chastise adds a Smite target and makes a critically striking Smite cast trigger a free Holy Nova. That is a different engine from Shield breaks or Shadow Word: Pain propagation.', ['Keep Smite working before expecting the capstone interaction.','With Chastise active, support the direct spell and relevant critical effects.','If recovery is the failure, take an available defensive choice rather than assuming this is the Discipline shield loop.']),
 'shaman':('Enhancement: a dated Windfury and wolves route','In the v0.130.0 snapshot, Windfury supports Lightning Bolt, Earth Shock and Frost Shock repeat hits; Maelstrom Weapon adds a free Chain Lightning interaction, and Feral Spirit summons two wolves. Later-version reworks are not checked here.', ['Support the Lightning Bolt or Shock spells actually available rather than borrowing a future wolf pair.','After Feral Spirit is allocated, inspect its Windfury wording separately from ordinary spell casts.','Do not apply this dated route to a newer changed Enhancement tree without reading its current nodes.']),
 'druid':('Restoration: recovery into a shield','Tree of Life turns healing beyond maximum health into a limited shield and supplies periodic Rejuvenation. This is separate from Balance’s repeated Starfire and Feral’s mutually exclusive forms.', ['Use the actual starting attack while developing recovery; do not expect an unallocated capstone shield.','Compare recovery and the damage needed to finish enemies together.','If survival is stable but a boss stalls, another recovery choice alone may not solve the failure.'])}
 for d in pages:
  s=d['slug']
  if s=='best-class/':d['parts'].insert(0,('finder','Find a starting direction',quiz()));d['related'].append(('abilities/','Look up a spell name'))
  if s=='addons/':
   d['parts'].insert(1,('catalog','Choose an author project by the job',table(['Project / author','Documented use','Open / source'],[
    ['AZS Spell Meter · kex0','Per-spell and timed damage views; use only when the built-in totals do not answer the question.','<code>/azsm</code> '+ext('https://github.com/kex0/AZSSpellMeter','GitHub · author project')+ref('meter')],
    ['SurvivorsDragonUi · migwynkriid13','Movable HUD, frames and layout editor. Compare with the stock interface before combining HUD replacements.','<code>/sdui</code> '+ext('https://github.com/migwynkriid13/SurvivorsDragonUi','GitHub · author project')+ref('sdui')],
    ['Azerloot · Kindagrey','Author documents a loot book, wishlist, build planning and recent-run chronicle.','<code>/azl</code> '+ext('https://github.com/Kindagrey/Azerloot','GitHub · author project')+ref('azerloot')]])+para('The two additional author READMEs were read 1 November 2026. Features are author-reported; current-game compatibility is not certified here. Follow each author’s release and installation instructions, install one relevant package first, then check it in a short attempt. These are external downloads, not files hosted by this guide.')))
  if s=='save-backup/':d['parts'].insert(0,('hosts','Original and third-party Play are different save locations',p('Our embedded Play page uses a third-party provider, whereas these export instructions describe Aethus’s original. A guide URL and a game-frame URL are different storage locations. Return to the provider and browser where the progress exists before exporting. We have not verified original-to-third-party import compatibility; preserve both sides before any replacement. '+a('play/#edition','Read the embedded edition scope'))))
  if s=='zones-bosses/':d['parts'].append(('prepare','Prepare for an encounter instead of only watching the timer',steps(['Check the selected class, zone eligibility and difficulty first.','Use the original Elwynn clock above to plan a pause in shopping or drafting before the next arrival.','If a piece is missing, inspect Armory → Drop Tables for this class and target the listed encounter.','If a run fails, use Death Recap to separate incoming avoidable damage from outgoing damage.','Compare one change at the same investment before treating a different zone or Heroic tier as the cure.'])+p(a('armory/','Target the missing gear')+' · '+a('damage-meter/#death-recap','Read the failure')+' · '+a('troubleshooting/','Separate startup problems'))))
  if s.startswith('builds/') and s.count('/')==2 and s.split('/')[1]in thirds:
   title,intro,order=thirds[s.split('/')[1]];d['parts'].append(('third-route',title,p(intro)+steps(order)+p('This is an editorial route decision from the preserved snapshot, not a complete legal point allocation or measured best build. '+a('talents/','Inspect prerequisites and gates'))))
  if s in ['best-class/','addons/','save-backup/','zones-bosses/'] or (s.startswith('builds/')and s.count('/')==2 and s.split('/')[1]in thirds):d['review_note']='Edited 1 November 2026 · New advice scoped to original v0.130.0 snapshot; earlier sections retain their dates · No new full-run test'
 return pages+new_pages()

def home_search(pages):
 rows=[]
 for d in pages:
  if d.get('lang','en')!='en':continue
  tokens=' '.join([d['title'],d['h1'],re.sub('<[^>]+>',' ',d['answer'])]+[t for _,t,_ in d['parts']])
  tokens=re.sub(r'\{\{s:\w+\}\}', '', tokens)
  rows.append('<li data-guide-search="'+escape(tokens,quote=True)+'">'+a(d['slug'],escape(d['title'].replace('Azeroth Survivors ','')))+'</li>')
 return '<section class="section" id="find"><h2>Find your next task</h2><p>'+a('troubleshooting/','Fix loading or WebGPU')+' · '+a('abilities/','Look up a spell name')+' · '+a('best-class/#finder','Find a class')+'</p><form id="guide-search" class="az-tool"><label>Search this guide <input id="guide-query" type="search" maxlength="120" placeholder="Try WebGPU, addons, Heroic or Warlock" autocomplete="off"></label><button type="reset">Clear search</button><p id="guide-status" role="status">Search page names, topics and starting advice. No account or upload.</p><ul id="guide-results" hidden>'+''.join(rows)+'</ul></form><noscript><p>Use the guide groups below; the local search needs JavaScript.</p></noscript></section>'
